Concrete skill pipeline. Define an AcademicWritingSkill exposing five composable skills, each independently testable.

class AcademicWritingSkill:
    def outline_skill(self, topic: str, refs: list[Ref]) -> Outline:
        '''Two-stage STORM pattern: gather/cluster refs, then emit a fixed IMRaD scaffold with refs bucketed per section. Returns Outline(sections=[Section(name, ref_ids, notes)]).'''

    def draft_section(self, section_name: str, refs: list[Ref], notes: str) -> str:
        '''Per-section call (never whole-paper). Prompt MUST instruct: use only supplied notes/results, cite only validated refs by key, stay within the section's IMRaD role. Returns markdown/LaTeX with inline \\cite{key}.'''

    def chain_of_density(self, text: str, target_words: int, iterations: int = 3) -> str:
        '''Start sparse, iteratively add 1-3 missing salient entities per pass while holding length == target_words. Enforce word count after each pass; truncate-and-retry on overrun.'''

    def validate_citations(self, bibtex_entries: list[str]) -> list[CitationResult]:
        '''Deterministic-first cascade below. Returns per-entry {valid, source, flagged_for_review, normalized_bibtex}.'''

    def style_transfer(self, text: str, source_style='casual', target_style='formal') -> str:
        '''Prompt-based TST with in-context formal exemplars; run as a final unification pass over the assembled draft.'''

Citation validation cascade (deterministic before LLM):

def validate_one(entry: str) -> CitationResult:
    rec = bibtexparser.loads(entry).entries[0]
    # 1. regex-extract a DOI / arXiv id from doi/url/eprint fields
    ident = extract_doi_or_arxiv(rec)
    if ident:
        # 2. habanero Crossref lookup (or arXiv API) -> compare title + first-author
        meta = Crossref(mailto=POLITE_EMAIL).works(ids=ident) if is_doi(ident) else arxiv_lookup(ident)
        if meta and title_match(meta, rec) and author_overlap(meta, rec) >= 0.60:
            return CitationResult(valid=True, source='crossref/arxiv', normalized=to_bibtex(meta))
        return CitationResult(valid=False, flagged_for_review=True)  # identifier conflict
    # 3. no identifier -> Semantic Scholar / scholarly title search fallback
    hit = semanticscholar_title_search(rec.get('title'))
    if hit and author_overlap(hit, rec) >= 0.60:
        return CitationResult(valid=True, source='semantic_scholar', normalized=to_bibtex(hit))
    return CitationResult(valid=False, flagged_for_review=True)  # likely hallucinated

Bibtex keys are deduplicated (firstauthorYEAR + a/b/c). DSPy module stub for the outline generator:

import dspy
class GenerateIMRaDOutline(dspy.Signature):
    '''Produce an IMRaD outline (Introduction, Methods, Results, Discussion) from a topic and references. Assign each reference id to the most relevant section.'''
    topic = dspy.InputField()
    references = dspy.InputField(desc='list of {id, title, abstract}')
    outline = dspy.OutputField(desc='JSON: sections[].{name, ref_ids, key_points}')

class OutlineModule(dspy.Module):
    def __init__(self):
        self.gen = dspy.ChainOfThought(GenerateIMRaDOutline)
    def forward(self, topic, references):
        return self.gen(topic=topic, references=references)

